import { reactRouter } from "@react-router/dev/vite";
import tailwindcss from "@tailwindcss/vite";
import { defineConfig } from "vite";
import tsconfigPaths from "vite-tsconfig-paths";

export default defineConfig({
  plugins: [tailwindcss(), reactRouter(), tsconfigPaths()],
});

import { alpha, createTheme, responsiveFontSizes } from "@mui/material/styles";
import type { ThemeOptions } from "@mui/material/styles";

const sharedTypography: ThemeOptions["typography"] = {
  fontFamily: "Roboto, sans-serif",
  h4: {
    fontWeight: 700,
    letterSpacing: "-0.02em",
  },
  h5: {
    fontWeight: 700,
    letterSpacing: "-0.015em",
  },
  h6: {
    fontWeight: 700,
  },
  subtitle1: {
    fontWeight: 500,
  },
  button: {
    textTransform: "none",
    fontWeight: 600,
  },
};

function componentsForMode(mode: "light" | "dark"): ThemeOptions["components"] {
  const paperShadow =
    mode === "light"
      ? "0 10px 28px rgba(15, 23, 42, 0.06)"
      : "0 10px 28px rgba(0, 0, 0, 0.45)";
  const cardShadow =
    mode === "light"
      ? "0 10px 30px rgba(11, 110, 230, 0.08)"
      : "0 10px 30px rgba(0, 0, 0, 0.5)";

  return {
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 16,
          boxShadow: cardShadow,
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          borderRadius: 16,
          boxShadow: paperShadow,
        },
      },
    },
    MuiButton: {
      defaultProps: {
        size: "large",
      },
      styleOverrides: {
        root: {
          borderRadius: 12,
          minHeight: 44,
          paddingInline: 16,
          transition: "box-shadow 0.2s ease, background-color 0.2s ease",
        },
        containedPrimary: ({ theme }) => ({
          boxShadow:
            mode === "light"
              ? `0 2px 10px ${alpha(theme.palette.primary.main, 0.32)}`
              : `0 2px 12px ${alpha(theme.palette.primary.main, 0.42)}`,
          "&:hover": {
            boxShadow:
              mode === "light"
                ? `0 4px 16px ${alpha(theme.palette.primary.main, 0.44)}`
                : `0 4px 18px ${alpha(theme.palette.primary.main, 0.52)}`,
          },
          "&:active": {
            boxShadow:
              mode === "light"
                ? `0 2px 8px ${alpha(theme.palette.primary.main, 0.36)}`
                : `0 2px 10px ${alpha(theme.palette.primary.main, 0.45)}`,
          },
          "&:disabled": {
            boxShadow: "none",
          },
        }),
        outlinedPrimary: ({ theme }) => ({
          borderWidth: "1px",
          backgroundColor: alpha(theme.palette.primary.main, 0.07),
          "&:hover": {
            borderWidth: "1px",
            backgroundColor: alpha(theme.palette.primary.main, 0.14),
          },
        }),
      },
    },
    MuiTextField: {
      defaultProps: {
        size: "small",
      },
    },
    MuiOutlinedInput: {
      styleOverrides: {
        root: ({ theme }) => ({
          boxSizing: "border-box",
          backgroundColor:
            mode === "light"
              ? alpha(theme.palette.primary.main, 0.04)
              : alpha(theme.palette.primary.main, 0.09),
          transition: theme.transitions.create(
            ["box-shadow", "background-color", "border-color"],
            { duration: theme.transitions.duration.shorter },
          ),
          boxShadow:
            mode === "light"
              ? "0 1px 2px rgba(15, 23, 42, 0.05)"
              : "0 1px 2px rgba(0, 0, 0, 0.25)",
          "&:hover": {
            backgroundColor:
              mode === "light"
                ? alpha(theme.palette.primary.main, 0.065)
                : alpha(theme.palette.primary.main, 0.13),
          },
          "& .MuiOutlinedInput-notchedOutline": {
            borderWidth: "1px",
            borderColor:
              mode === "light"
                ? alpha(theme.palette.common.black, 0.17)
                : alpha(theme.palette.common.white, 0.22),
          },
          "&:hover .MuiOutlinedInput-notchedOutline": {
            borderColor:
              mode === "light"
                ? alpha(theme.palette.common.black, 0.26)
                : alpha(theme.palette.common.white, 0.32),
          },
          "&.Mui-focused": {
            backgroundColor:
              mode === "light"
                ? "#ffffff"
                : alpha(theme.palette.background.paper, 0.98),
            boxShadow: `0 0 0 3px ${alpha(theme.palette.primary.main, 0.13)}`,
          },
          "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
            borderWidth: "1px",
            borderColor: theme.palette.primary.main,
          },
          "&.Mui-disabled": {
            backgroundColor: theme.palette.action.hover,
            boxShadow: "none",
          },
        }),
      },
    },
    MuiFormLabel: {
      styleOverrides: {
        root: ({ theme }) => ({
          "&:not(.Mui-error)": {
            color:
              mode === "light"
                ? alpha(theme.palette.text.primary, 0.62)
                : alpha(theme.palette.common.white, 0.68),
          },
          "&.Mui-focused:not(.Mui-error)": {
            color: theme.palette.primary.main,
          },
        }),
      },
    },
    MuiFormHelperText: {
      styleOverrides: {
        root: ({ theme }) => ({
          "&:not(.Mui-error)": {
            color:
              mode === "light"
                ? alpha(theme.palette.text.primary, 0.55)
                : alpha(theme.palette.common.white, 0.55),
          },
        }),
      },
    },
    MuiMenuItem: {
      styleOverrides: {
        root: {
          fontWeight: 500,
        },
      },
    },
    MuiFormControl: {
      defaultProps: {
        size: "small",
      },
    },
    MuiTableCell: {
      styleOverrides: {
        head: {
          fontWeight: 700,
        },
      },
    },
  };
}

const lightPalette: ThemeOptions["palette"] = {
  mode: "light",
  primary: {
    main: "#0b6ee6",
    light: "#4f93ff",
    dark: "#0048b3",
  },
  secondary: {
    main: "#6f42c1",
  },
  background: {
    default: "#f3f6fb",
    paper: "#ffffff",
  },
  success: {
    main: "#1b8a4b",
  },
  warning: {
    main: "#d17a00",
  },
  error: {
    main: "#c62828",
  },
};

const darkPalette: ThemeOptions["palette"] = {
  mode: "dark",
  primary: {
    main: "#5b9fff",
    light: "#82b4ff",
    dark: "#2f6fcc",
  },
  secondary: {
    main: "#b794f6",
  },
  background: {
    default: "#0f1419",
    paper: "#1a2332",
  },
  success: {
    main: "#4caf50",
  },
  warning: {
    main: "#ffb74d",
  },
  error: {
    main: "#ef5350",
  },
};

export function createAppTheme(mode: "light" | "dark") {
  const palette = mode === "light" ? lightPalette : darkPalette;
  const base = createTheme({
    palette,
    shape: {
      borderRadius: 14,
    },
    spacing: 8,
    typography: sharedTypography,
    components: componentsForMode(mode),
  });
  return responsiveFontSizes(base);
}

export const appTheme = createAppTheme("light");

import * as React from "react";

export type ColorSchemePreference = "light" | "dark" | "system";

export type ResolvedColorMode = "light" | "dark";

export const COLOR_MODE_STORAGE_KEY = "learningdb-second-color-mode";

export type ColorModeContextValue = {
  preference: ColorSchemePreference;
  setPreference: (preference: ColorSchemePreference) => void;
  resolvedMode: ResolvedColorMode;
};

export const ColorModeContext = React.createContext<ColorModeContextValue | null>(null);

export function useColorMode(): ColorModeContextValue {
  const ctx = React.useContext(ColorModeContext);
  if (!ctx) {
    throw new Error("useColorMode must be used within ColorModeContext.Provider");
  }
  return ctx;
}

/**
 * Browser: FastAPI on same host as the page, port 8000, path prefix /api.
 * SSR / no window: fall back to VITE_API_BASE_URL (build-time default).
 */
export function resolveBackendApiBaseUrl(): string {
  const fallback = import.meta.env.VITE_API_BASE_URL ?? "http://localhost:8000/api";
  if (typeof window === "undefined") {
    return fallback;
  }
  const { protocol, hostname } = window.location;
  return `${protocol}//${hostname}:8000/api`;
}

import axios from "axios";
import { resolveBackendApiBaseUrl } from "./resolveApiBaseUrl";

const API_BASE_URL = resolveBackendApiBaseUrl();

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    "Content-Type": "application/json",
  },
});

export const getHealth = () => api.get<{ status: string }>("/health");

export interface Column {
  name: string;
  type: string;
  nullable: boolean;
  is_primary_key: boolean;
  autoincrement: boolean;
  enums?: string[];
}

export interface ActivityData {
  ACTIVITY_ID: number;
  ACT_NAME: string;
  ACT_STATUS?: string;
  Total?: number;
  Learning?: number;
  Overview?: number;
  Practice?: number;
}

export interface ActivityLog {
  ACTIVITY_ID: number;
  ACTI_LOG_ID: number;
  ACT_NAME: string;
  START_TIME: string;
}

export interface ActivityOutput {
  AO_ID: number;
  ACT_NAME: string;
  START_TIME: string;
  FINISH_TIME: string;
}

export interface BayesResult {
  ACTIVITY_ID: number;
  ACT_NAME: string;
  Total: number;
  Learning: number;
  Overview: number;
  Practice: number;
}

export const getTables = () => api.get<{ tables: string[] }>("/tables");

export const getTableColumns = (tableName: string) =>
  api.get<{ columns: Column[] }>(`/tables/${tableName}/columns`);

export const insertRecord = (tableName: string, data: Record<string, unknown>) =>
  api.post("/tables/insert", { table_name: tableName, data });

export interface TableRowsResponse {
  rows: Record<string, unknown>[];
  total: number;
}

export interface ListTableRowsParams {
  limit?: number;
  offset?: number;
  sort_by?: string | null;
  sort_dir?: "asc" | "desc";
  filters?: Record<string, unknown>;
}

export const listTableRows = (tableName: string, params: ListTableRowsParams = {}) => {
  const { limit, offset, sort_by, sort_dir, filters } = params;
  return api.get<TableRowsResponse>(`/tables/${encodeURIComponent(tableName)}/rows`, {
    params: {
      limit,
      offset,
      sort_by: sort_by ?? undefined,
      sort_dir: sort_dir ?? undefined,
      filters:
        filters && Object.keys(filters).length > 0 ? JSON.stringify(filters) : undefined,
    },
  });
};

export const updateTableRow = (
  tableName: string,
  primaryKey: Record<string, unknown>,
  updates: Record<string, unknown>,
) =>
  api.patch(`/tables/${encodeURIComponent(tableName)}/rows`, {
    primary_key: primaryKey,
    updates,
  });

export const deleteTableRow = (tableName: string, primaryKey: Record<string, unknown>) =>
  api.delete(`/tables/${encodeURIComponent(tableName)}/rows`, {
    data: { primary_key: primaryKey },
  });

export const getActivityIds = (status?: string) =>
  api.get<{ activity_ids: number[] }>("/activities", { params: { status } });

export const getActivityList = (userId: number) =>
  api.get<{ data: ActivityData[] }>(`/activities/list/${userId}`);

export const getActivityView = (userId: number) =>
  api.get<{ data: ActivityData[] }>(`/activities/view/${userId}`);

export const getCurrentActivityLog = (userId: number) =>
  api.get<{ data: ActivityLog[] }>(`/activities/current-log/${userId}`);

export const getCurrentActivityOutput = (userId: number) =>
  api.get<{ data: ActivityOutput[] }>(`/activities/current-output/${userId}`);

export const updatePrior = (activityId: number, prob: number) =>
  api.post("/update/prior", { activity_id: activityId, prob });

export const updatePosterior = (activityId: number, columnChoice: number, prob: number) =>
  api.post("/update/posterior", { activity_id: activityId, column_choice: columnChoice, prob });

export const updateStatus = (activityId: number, status: string) =>
  api.post("/update/status", { activity_id: activityId, status });

export const updateZero = () => api.post("/update/zero");

export const checkPrior = () =>
  api.get<{ valid: boolean; total: number; message: string }>("/bayes/check-prior");

export const runBayes = (totalMinute?: number) =>
  api.get<{ data: BayesResult[] }>("/bayes/run", { params: { total_minute: totalMinute } });

export interface UserProfile {
  user_id: number;
  user_location: string;
}

export const getUserProfile = (userId: number) =>
  api.get<{ data: UserProfile }>(`/users/${userId}/profile`);

export default api;

import * as React from "react";
import {
  isRouteErrorResponse,
  Links,
  Meta,
  Outlet,
  Scripts,
  ScrollRestoration,
} from "react-router";
import { CssBaseline, ThemeProvider, useMediaQuery } from "@mui/material";

import type { Route } from "./+types/root";
import "./app.css";
import "@fontsource/roboto/300.css";
import "@fontsource/roboto/400.css";
import "@fontsource/roboto/500.css";
import "@fontsource/roboto/700.css";
import {
  COLOR_MODE_STORAGE_KEY,
  ColorModeContext,
  type ColorSchemePreference,
} from "./color-mode";
import { createAppTheme } from "./theme";

function resolveColorMode(
  preference: ColorSchemePreference,
  prefersDark: boolean,
): "light" | "dark" {
  if (preference === "system") {
    return prefersDark ? "dark" : "light";
  }
  return preference;
}

export const links: Route.LinksFunction = () => [
  { rel: "icon", type: "image/png", href: "/learningdblogo.png" },
  { rel: "apple-touch-icon", href: "/learningdblogo.png" },
  { rel: "preconnect", href: "https://fonts.googleapis.com" },
  {
    rel: "preconnect",
    href: "https://fonts.gstatic.com",
    crossOrigin: "anonymous",
  },
  {
    rel: "stylesheet",
    href: "https://fonts.googleapis.com/css2?family=Roboto:wght@300;400;500;700&display=swap",
  },
];

export function Layout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <Meta />
        <Links />
      </head>
      <body>
        {children}
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  );
}

function AppThemeShell() {
  const [preference, setPreference] = React.useState<ColorSchemePreference>("light");
  const [storageReady, setStorageReady] = React.useState(false);
  const prefersDark = useMediaQuery("(prefers-color-scheme: dark)", { noSsr: true });

  React.useEffect(() => {
    try {
      const stored = localStorage.getItem(COLOR_MODE_STORAGE_KEY);
      if (stored === "light" || stored === "dark" || stored === "system") {
        setPreference(stored);
      }
    } catch {
      /* ignore */
    }
    setStorageReady(true);
  }, []);

  const resolvedMode = resolveColorMode(preference, prefersDark);

  React.useEffect(() => {
    document.documentElement.setAttribute("data-theme", resolvedMode);
    if (!storageReady) {
      return;
    }
    try {
      localStorage.setItem(COLOR_MODE_STORAGE_KEY, preference);
    } catch {
      /* ignore */
    }
  }, [preference, resolvedMode, storageReady]);

  const theme = React.useMemo(() => createAppTheme(resolvedMode), [resolvedMode]);

  const colorModeValue = React.useMemo(
    () => ({
      preference,
      setPreference,
      resolvedMode,
    }),
    [preference, resolvedMode],
  );

  return (
    <ColorModeContext.Provider value={colorModeValue}>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Outlet />
      </ThemeProvider>
    </ColorModeContext.Provider>
  );
}

export default function App() {
  return <AppThemeShell />;
}

export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
  let message = "Oops!";
  let details = "An unexpected error occurred.";
  let stack: string | undefined;

  if (isRouteErrorResponse(error)) {
    message = error.status === 404 ? "404" : "Error";
    details =
      error.status === 404
        ? "The requested page could not be found."
        : error.statusText || details;
  } else if (import.meta.env.DEV && error && error instanceof Error) {
    details = error.message;
    stack = error.stack;
  }

  return (
    <main className="pt-16 p-4 container mx-auto">
      <h1>{message}</h1>
      <p>{details}</p>
      {stack && (
        <pre className="w-full p-4 overflow-x-auto">
          <code>{stack}</code>
        </pre>
      )}
    </main>
  );
}

@import "tailwindcss";

@theme {
  --font-sans: "Roboto", ui-sans-serif, system-ui, sans-serif,
    "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
}

html,
body {
  min-height: 100%;
  margin: 0;
}

html[data-theme="light"] body,
html:not([data-theme]) body {
  background: radial-gradient(circle at top, #f8fbff 0%, #f3f6fb 55%, #edf2fa 100%);
}

html[data-theme="dark"] body {
  background: radial-gradient(circle at top, #1a2332 0%, #0f1419 55%, #0a0e14 100%);
}

* {
  box-sizing: border-box;
}

a {
  color: inherit;
}

#root {
  min-height: 100vh;
}

import { type RouteConfig, index, layout, route } from "@react-router/dev/routes";

export default [
  layout("routes/app-shell.tsx", [
    index("routes/home.tsx"),
    route("data-entry", "routes/data-entry.tsx"),
  ]),
] satisfies RouteConfig;

import MenuBookOutlinedIcon from "@mui/icons-material/MenuBookOutlined";
import {
  AppBar,
  Box,
  Button,
  Container,
  IconButton,
  Toolbar,
  Typography,
} from "@mui/material";
import { Link, Outlet } from "react-router";

import type { Route } from "./+types/app-shell";
import { useColorMode } from "~/color-mode";

export default function AppShell() {
  const { preference, setPreference, resolvedMode } = useColorMode();

  return (
    <Box sx={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <AppBar position="sticky" color="inherit" elevation={0} sx={{ borderBottom: 1, borderColor: "divider" }}>
        <Toolbar>
          <MenuBookOutlinedIcon color="primary" sx={{ mr: 1 }} />
          <Typography component={Link} to="/" variant="h6" sx={{ flexGrow: 1, textDecoration: "none", color: "inherit" }}>
            LearningDB (CRUD)
          </Typography>
          <Button component={Link} to="/" color="inherit" size="small">
            Home
          </Button>
          <Button component={Link} to="/data-entry" color="inherit" size="small">
            Data entry
          </Button>
          <IconButton
            size="small"
            aria-label="toggle color mode"
            onClick={() => {
              const next =
                preference === "light" ? "dark" : preference === "dark" ? "system" : "light";
              setPreference(next);
            }}
            sx={{ ml: 1 }}
          >
            <Typography variant="caption" sx={{ minWidth: 52 }}>
              {resolvedMode === "dark" ? "Dark" : "Light"}
            </Typography>
          </IconButton>
        </Toolbar>
      </AppBar>
      <Container maxWidth="lg" sx={{ py: 3, flex: 1 }}>
        <Outlet />
      </Container>
    </Box>
  );
}

export function meta({}: Route.MetaArgs) {
  return [{ title: "LearningDB — second app" }];
}

import CheckCircleOutlineIcon from "@mui/icons-material/CheckCircleOutline";
import ErrorOutlineIcon from "@mui/icons-material/ErrorOutline";
import { Alert, Card, CardContent, Stack, Typography } from "@mui/material";
import { Link } from "react-router";

import type { Route } from "./+types/home";
import { getHealth } from "~/services/api";

export function meta({}: Route.MetaArgs) {
  return [
    { title: "LearningDB — CRUD app" },
    { name: "description", content: "Second LearningDB web app (FastAPI CRUD only)" },
  ];
}

export async function loader() {
  try {
    const { data } = await getHealth();
    return { ok: data.status === "healthy", message: null as string | null };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "Could not reach API";
    return { ok: false, message: msg };
  }
}

export default function Home({ loaderData }: Route.ComponentProps) {
  const { ok, message } = loaderData;

  return (
    <Stack spacing={3}>
      <Typography variant="h4" component="h1">
        CRUD workspace
      </Typography>
      <Typography color="text.secondary">
        This app talks to the same FastAPI backend on port <strong>8000</strong> (no orchestrator). Dev server
        runs on port <strong>3001</strong> so it does not conflict with the main app on 3000.
      </Typography>
      <Card>
        <CardContent>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
            {ok ? (
              <CheckCircleOutlineIcon color="success" fontSize="large" />
            ) : (
              <ErrorOutlineIcon color="error" fontSize="large" />
            )}
            <Typography variant="h6">API health</Typography>
          </Stack>
          {ok ? (
            <Alert severity="success">GET /api/health returned healthy.</Alert>
          ) : (
            <Alert severity="error">
              {message ?? "Backend unreachable. Start the API (e.g. docker compose service api) and reload."}
            </Alert>
          )}
        </CardContent>
      </Card>
      <Typography>
        Next: open the <Link to="/data-entry">data entry</Link> screen (placeholder for Stitch-driven layout).
      </Typography>
    </Stack>
  );
}

import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import { Alert, Card, CardContent, Stack, Typography } from "@mui/material";

import type { Route } from "./+types/data-entry";
import { stitchDesignReadmePath, stitchPlaceholderTokens } from "~/design-tokens";

export function meta({}: Route.MetaArgs) {
  return [
    { title: "Data entry — LearningDB" },
    { name: "description", content: "Experimental data entry UI (Stitch-ready)" },
  ];
}

export default function DataEntryRoute() {
  return (
    <Stack spacing={3}>
      <Typography variant="h4" component="h1">
        Data entry
      </Typography>
      <Alert icon={<InfoOutlinedIcon fontSize="inherit" />} severity="info">
        Placeholder route for the new input screen. Drop Google Stitch exports under{" "}
        <code>{stitchDesignReadmePath}</code> and map tokens in{" "}
        <code>app/design-tokens.ts</code> (see <code>primary</code> sample: {stitchPlaceholderTokens.primary}).
      </Alert>
      <Card>
        <CardContent>
          <Typography variant="body1" color="text.secondary">
            Form fields and layout will follow your Stitch design system once assets are in the repo.
          </Typography>
        </CardContent>
      </Card>
    </Stack>
  );
}

/**
 * Bridge for a future Google Stitch / design-system export.
 * Replace or extend `stitchPlaceholderTokens` when token files land in `design/stitch/`.
 */
export const stitchDesignReadmePath = "design/stitch/README.md";

/** Sample keys to align MUI theme later; values mirror app 1 primary until Stitch overrides. */
export const stitchPlaceholderTokens = {
  primary: "#0b6ee6",
  surface: "#ffffff",
  radiusMd: "14px",
} as const;

