export type WizardStep = 1 | 2 | 3;

export interface ImportDraftV1 {
  version: 1;
  step: WizardStep;
  actiLogId: number | null;
  aoId: number | null;
  logValues: Record<string, unknown>;
  outputValues: Record<string, unknown>;
  kitValues: Record<string, unknown>;
}

import type { ImportDraftV1 } from "./types";

const KEY = "learningdb-second-import-wizard-draft-v1";

export function loadDraft(): ImportDraftV1 | null {
  if (typeof window === "undefined") {
    return null;
  }
  try {
    const raw = sessionStorage.getItem(KEY);
    if (!raw) {
      return null;
    }
    const parsed = JSON.parse(raw) as ImportDraftV1;
    if (parsed?.version !== 1) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

export function saveDraft(draft: ImportDraftV1): void {
  if (typeof window === "undefined") {
    return;
  }
  sessionStorage.setItem(KEY, JSON.stringify(draft));
}

export function clearDraft(): void {
  if (typeof window === "undefined") {
    return;
  }
  sessionStorage.removeItem(KEY);
}

import type { Column } from "~/services/api";
import { getTables } from "~/services/api";

const LOGICAL = {
  log: "ACTIVITY_LOG",
  output: "ACTIVITY_OUTPUT",
  kit: "KIT_COUNT",
} as const;

export type ResolvedTables = { log: string; output: string; kit: string };

export async function resolveImportTables(): Promise<ResolvedTables> {
  const { data } = await getTables();
  const names = data.tables;
  const pick = (logical: string) => {
    const found = names.find((t) => t.toLowerCase() === logical.toLowerCase());
    if (!found) {
      throw new Error(`Table "${logical}" not found in database.`);
    }
    return found;
  };
  return {
    log: pick(LOGICAL.log),
    output: pick(LOGICAL.output),
    kit: pick(LOGICAL.kit),
  };
}

/** Parse MySQL SET('a','b') style literals from reflected type string. */
export function parseSetMembers(typeStr: string): string[] | null {
  if (!typeStr.toUpperCase().includes("SET")) {
    return null;
  }
  const out: string[] = [];
  const re = /'([^']*)'/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(typeStr)) !== null) {
    out.push(m[1]);
  }
  return out.length ? out : null;
}

export function isNumericType(typeStr: string): boolean {
  const u = typeStr.toUpperCase();
  return (
    u.includes("INT") ||
    u.includes("DECIMAL") ||
    u.includes("FLOAT") ||
    u.includes("DOUBLE") ||
    u.includes("BIGINT")
  );
}

export function isBoolTinyint(typeStr: string, colName: string): boolean {
  const u = typeStr.toUpperCase();
  return u.includes("TINYINT") || colName === "AC_ON" || colName === "TARGET_MET";
}

export function buildInsertPayload(
  columns: Column[],
  values: Record<string, unknown>,
  inject?: Record<string, unknown>,
): Record<string, unknown> {
  const payload: Record<string, unknown> = { ...inject };
  for (const col of columns) {
    if (col.is_primary_key && col.autoincrement) {
      continue;
    }
    if (inject && Object.prototype.hasOwnProperty.call(inject, col.name)) {
      continue;
    }
    const raw = values[col.name];
    if (raw === undefined || raw === "") {
      if (!col.nullable && !col.autoincrement) {
        throw new Error(`Missing required field: ${col.name}`);
      }
      continue;
    }
    if (typeof raw === "string" && col.enums?.length && !col.enums.includes(raw)) {
      throw new Error(`Invalid enum for ${col.name}`);
    }
    if (isNumericType(col.type)) {
      const n = Number(raw);
      if (Number.isNaN(n)) {
        throw new Error(`Invalid number for ${col.name}`);
      }
      payload[col.name] = n;
      continue;
    }
    if (isBoolTinyint(col.type, col.name)) {
      payload[col.name] = raw === true || raw === 1 || raw === "1" ? 1 : 0;
      continue;
    }
    payload[col.name] = raw;
  }
  return payload;
}

export function extractPkInt(
  primaryKey: Record<string, unknown> | undefined,
  candidates: string[],
): number | null {
  if (!primaryKey) {
    return null;
  }
  const entries = Object.entries(primaryKey);
  for (const want of candidates) {
    const w = want.toLowerCase();
    for (const [k, v] of entries) {
      if (k.toLowerCase() !== w) {
        continue;
      }
      if (typeof v === "number" && Number.isFinite(v)) {
        return v;
      }
      if (typeof v === "string" && /^\d+$/.test(v)) {
        return Number(v);
      }
    }
  }
  for (const [, v] of entries) {
    if (typeof v === "number" && Number.isFinite(v)) {
      return v;
    }
  }
  return null;
}

import {
  Autocomplete,
  Checkbox,
  FormControl,
  FormControlLabel,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from "@mui/material";

import type { Column } from "~/services/api";
import { isBoolTinyint, isNumericType, parseSetMembers } from "./table-utils";

type Props = {
  columns: Column[];
  values: Record<string, unknown>;
  onChange: (name: string, value: unknown) => void;
  omit: Set<string>;
};

export function WizardFields({ columns, values, onChange, omit }: Props) {
  return (
    <Stack spacing={2.5}>
      {columns.map((col) => {
        if (omit.has(col.name)) {
          return null;
        }
        if (col.is_primary_key && col.autoincrement) {
          return null;
        }
        const v = values[col.name];
        const label = col.name.replace(/_/g, " ");

        if (col.enums?.length) {
          return (
            <FormControl key={col.name} fullWidth size="small" required={!col.nullable}>
              <InputLabel id={`${col.name}-lbl`}>{label}</InputLabel>
              <Select
                labelId={`${col.name}-lbl`}
                label={label}
                value={typeof v === "string" || typeof v === "number" ? v : ""}
                onChange={(e) => onChange(col.name, e.target.value)}
              >
                {col.nullable ? (
                  <MenuItem value="">
                    <em>None</em>
                  </MenuItem>
                ) : null}
                {col.enums.map((opt) => (
                  <MenuItem key={opt} value={opt}>
                    {opt}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          );
        }

        const setMembers = parseSetMembers(col.type);
        if (setMembers) {
          const selected = Array.isArray(v) ? (v as string[]) : typeof v === "string" && v ? v.split(",") : [];
          return (
            <Autocomplete
              key={col.name}
              multiple
              options={setMembers}
              value={selected}
              onChange={(_, newVal) => onChange(col.name, newVal)}
              renderInput={(params) => (
                <TextField {...params} label={label} helperText="MySQL SET — pick one or more" size="small" />
              )}
            />
          );
        }

        if (isBoolTinyint(col.type, col.name)) {
          return (
            <FormControlLabel
              key={col.name}
              control={
                <Checkbox
                  checked={v === true || v === 1 || v === "1"}
                  onChange={(e) => onChange(col.name, e.target.checked ? 1 : 0)}
                />
              }
              label={label}
            />
          );
        }

        if (col.type.toUpperCase().includes("TIME") && !col.type.toUpperCase().includes("STAMP")) {
          return (
            <TextField
              key={col.name}
              label={label}
              type="time"
              size="small"
              fullWidth
              InputLabelProps={{ shrink: true }}
              value={typeof v === "string" ? v : ""}
              onChange={(e) => onChange(col.name, e.target.value)}
              required={!col.nullable}
            />
          );
        }

        if (col.type.toUpperCase().includes("DATE") && !col.type.toUpperCase().includes("DATETIME")) {
          return (
            <TextField
              key={col.name}
              label={label}
              type="date"
              size="small"
              fullWidth
              InputLabelProps={{ shrink: true }}
              value={typeof v === "string" ? v : ""}
              onChange={(e) => onChange(col.name, e.target.value)}
              required={!col.nullable}
            />
          );
        }

        if (isNumericType(col.type)) {
          return (
            <TextField
              key={col.name}
              label={label}
              type="number"
              size="small"
              fullWidth
              value={v === undefined || v === null ? "" : v}
              onChange={(e) => onChange(col.name, e.target.value === "" ? "" : Number(e.target.value))}
              required={!col.nullable}
              inputProps={{ step: col.type.includes("DECIMAL") || col.type.includes("FLOAT") ? "0.01" : "1" }}
            />
          );
        }

        return (
          <TextField
            key={col.name}
            label={label}
            size="small"
            fullWidth
            multiline={col.type.toUpperCase().includes("TEXT") || col.type.toUpperCase().includes("VARCHAR(500)")}
            minRows={col.type.toUpperCase().includes("TEXT") ? 3 : 1}
            value={typeof v === "string" || typeof v === "number" ? v : ""}
            onChange={(e) => onChange(col.name, e.target.value)}
            required={!col.nullable}
            helperText={col.type}
          />
        );
      })}
      {columns.length === 0 ? <Typography color="text.secondary">Loading columns…</Typography> : null}
    </Stack>
  );
}

