+
+function FieldShell({
+  label,
+  helper,
+  children,
+}: {
+  label: string;
+  helper?: string;
+  children: React.ReactNode;
+}) {
+  return (
+    <div className="space-y-2">
+      <Label>{label}</Label>
+      {children}
+      {helper ? <p className="text-[0.7rem] text-[var(--color-on-surface-variant)]">{helper}</p> : null}
+    </div>
+  );
+}
+
+export function WizardFields({ columns, values, onChange, omit }: Props) {
+  const renderField = (col: Column) => {
+    if (omit.has(col.name)) {
+      return null;
+    }
+    if (col.is_primary_key && col.autoincrement) {
+      return null;
+    }
+
+    const value = values[col.name];
+    const label = col.name.replace(/_/g, " ");
+    const required = !col.nullable;
+    const upperType = col.type.toUpperCase();
+
+    if (col.enums?.length) {
+      return (
+        <FieldShell label={label} helper={col.type}>
+          <Select
+            value={typeof value === "string" || typeof value === "number" ? String(value) : ""}
+            onChange={(e) => onChange(col.name, e.target.value)}
+            required={required}
+          >
+            <option value="">{required ? "Select..." : "None"}</option>
+            {col.enums.map((opt) => (
+              <option key={opt} value={opt}>
+                {opt}
+              </option>
+            ))}
+          </Select>
+        </FieldShell>
+      );
+    }
+
+    const setMembers = parseSetMembers(col.type);
+    if (setMembers) {
+      const selected = Array.isArray(value) ? (value as string[]) : typeof value === "string" && value ? value.split(",") : [];
+      return (
+        <FieldShell label={label} helper="MySQL SET — choose one or more options">
+          <div className="flex flex-wrap gap-2 rounded-[var(--radius-md)] bg-[var(--color-surface-low)] p-2">
+            {setMembers.map((member) => {
+              const active = selected.includes(member);
+              return (
+                <Button
+                  key={member}
+                  type="button"
+                  size="sm"
+                  variant={active ? "default" : "ghost"}
+                  onClick={() => {
+                    const next = active ? selected.filter((v) => v !== member) : [...selected, member];
+                    onChange(col.name, next);
+                  }}
